#!/usr/bin/env node
// Regenerates src/theme/tokens.ts from the designer's prototype CSS, so the
// native app uses exactly the demo's colours and radius.
//
//   node scripts/sync-design-tokens.mjs <path-to-bitcoinsv-wallet-proto>
//
// Reads the `:root` (light) and `.dark` blocks of app/globals.css and converts
// every value to sRGB the way a browser does (OKLCH → OKLab → linear sRGB →
// gamma-encoded, clamped to gamut). Commit the regenerated file together with
// the prototype revision it came from.
import { readFileSync, writeFileSync } from 'node:fs'
import { execFileSync } from 'node:child_process'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const protoDir = process.argv[2]
if (!protoDir) {
  console.error('usage: node scripts/sync-design-tokens.mjs <path-to-bitcoinsv-wallet-proto>')
  process.exit(1)
}
const appDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const css = readFileSync(path.join(protoDir, 'app/globals.css'), 'utf8')

let revision = 'unknown'
try {
  revision = execFileSync('git', ['-C', protoDir, 'rev-parse', '--short', 'HEAD'], { encoding: 'utf8' }).trim()
  const dirty = execFileSync('git', ['-C', protoDir, 'status', '--porcelain', 'app/globals.css'], { encoding: 'utf8' }).trim()
  if (dirty) revision += ' (with uncommitted globals.css changes)'
} catch {}

/** The declarations of the first top-level block whose selector is `selector` and that defines `mustHave`. */
function block(selector, mustHave) {
  const re = new RegExp(`(^|\\n)${selector.replace('.', '\\.')}\\s*\\{([^}]*)\\}`, 'g')
  for (const m of css.matchAll(re)) {
    if (m[2].includes(mustHave)) return m[2]
  }
  throw new Error(`no ${selector} block defining ${mustHave} in globals.css`)
}

function declarations(body) {
  const out = {}
  for (const m of body.replace(/\/\*[\s\S]*?\*\//g, '').matchAll(/--([\w-]+)\s*:\s*([^;]+);/g)) {
    out[m[1]] = m[2].trim()
  }
  return out
}

const gamma = x => (x <= 0.0031308 ? 12.92 * x : 1.055 * Math.pow(x, 1 / 2.4) - 0.055)
const clamp = x => Math.min(1, Math.max(0, x))
const hex2 = x => Math.round(clamp(x) * 255).toString(16).padStart(2, '0')

function oklchToRgb(L, C, H) {
  const h = (H * Math.PI) / 180
  const a = C * Math.cos(h)
  const b = C * Math.sin(h)
  const l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3
  const m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3
  const s = (L - 0.0894841775 * a - 1.291485548 * b) ** 3
  return [
    gamma(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s),
    gamma(-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s),
    gamma(-0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s)
  ]
}

/** CSS colour → '#rrggbb' or '#rrggbbaa'. Non-colours (e.g. the radius) return null. */
function toColor(value) {
  const v = value.trim().toLowerCase()
  if (/^#[0-9a-f]{6}$/.test(v)) return v
  if (/^#[0-9a-f]{3}$/.test(v)) return '#' + [...v.slice(1)].map(c => c + c).join('')
  const m = v.match(/^oklch\(\s*([\d.]+%?)\s+([\d.]+)\s+([\d.]+)\s*(?:\/\s*([\d.]+%?))?\s*\)$/)
  if (!m) return null
  const L = m[1].endsWith('%') ? parseFloat(m[1]) / 100 : parseFloat(m[1])
  const [r, g, b] = oklchToRgb(L, parseFloat(m[2]), parseFloat(m[3]))
  let out = '#' + hex2(r) + hex2(g) + hex2(b)
  if (m[4] !== undefined) {
    const alpha = m[4].endsWith('%') ? parseFloat(m[4]) / 100 : parseFloat(m[4])
    out += hex2(alpha)
  }
  return out
}

const camel = name => name.replace(/-(\w)/g, (_, c) => c.toUpperCase())

function palette(decls) {
  const out = {}
  for (const [name, value] of Object.entries(decls)) {
    if (name.startsWith('sidebar')) continue // web-only desktop sidebar
    const color = toColor(value)
    if (color) out[camel(name)] = color
  }
  return out
}

const lightDecls = declarations(block(':root', '--gold:'))
const light = palette(lightDecls)
const dark = { ...light, ...palette(declarations(block('.dark', '--background:'))) }

const radiusRem = parseFloat(lightDecls.radius)
if (!Number.isFinite(radiusRem)) throw new Error('globals.css --radius is not a rem value')
const radius = radiusRem * 16
// Tailwind's radius scale in the prototype's @theme block.
const radii = { sm: radius * 0.6, md: radius * 0.8, lg: radius, xl: radius * 1.4, '2xl': radius * 1.8, '3xl': radius * 2.2, '4xl': radius * 2.6 }

const fmt = obj =>
  Object.entries(obj)
    .map(([k, v]) => `  ${/^[A-Za-z_]\w*$/.test(k) ? k : `'${k}'`}: ${typeof v === 'number' ? +v.toFixed(2) : `'${v}'`}`)
    .join(',\n')

const file = `// GENERATED by scripts/sync-design-tokens.mjs from the prototype's
// app/globals.css at revision ${revision}. Do not edit by hand: change the
// prototype's tokens and regenerate, so the two stay identical.

export const light = {
${fmt(light)}
} as const

export const dark = {
${fmt(dark)}
} as const

export type ColorToken = keyof typeof light
export type Palette = Record<ColorToken, string>

/** Corner radii in points (the prototype's Tailwind radius scale at 16px/rem). */
export const radii = {
${fmt(radii)}
} as const
`

const outPath = path.join(appDir, 'src/theme/tokens.ts')
writeFileSync(outPath, file)
console.log(`wrote ${path.relative(appDir, outPath)} (${Object.keys(light).length} colours, prototype ${revision})`)
